//! Push notifications generated by the proxy itself: `UserDataChanged`
//! (play state, favourites, ...) and `LibraryChanged` (the index changed).
//! Both tasks hold a `Weak<AppState>`.

use super::envelope;
use crate::index::snapshot::Snapshot;
use crate::proxy::{self, Client};
use crate::types::{ProxyItemId, ServerId};
use crate::userdata::view;
use crate::{AppState, Shared};
use serde_json::{json, Value};
use std::collections::{BTreeSet, HashMap};
use std::sync::Weak;
use std::time::Duration;
use tokio::sync::broadcast::error::RecvError;

/// Jellyfin's `UserDataChangeNotifier.UpdateDuration`.
const DEBOUNCE: Duration = Duration::from_millis(500);

/// Send each user's changed item data to their sessions, 500 ms after the
/// last change.
pub fn spawn_userdata(weak: Weak<AppState>) {
    let Some(st) = weak.upgrade() else { return };
    let mut rx = st.userdata.subscribe();
    drop(st);
    tokio::spawn(async move {
        let mut pending: HashMap<String, BTreeSet<ProxyItemId>> = HashMap::new();
        loop {
            let ev = if pending.is_empty() {
                rx.recv().await
            } else {
                match tokio::time::timeout(DEBOUNCE, rx.recv()).await {
                    Ok(ev) => ev,
                    Err(_) => {
                        let Some(st) = weak.upgrade() else { return };
                        flush(&st, std::mem::take(&mut pending));
                        continue;
                    }
                }
            };
            match ev {
                Ok(e) => pending.entry(e.user).or_default().extend(e.items),
                Err(RecvError::Lagged(_)) => {}
                Err(RecvError::Closed) => return,
            }
        }
    });
}

fn flush(st: &AppState, pending: HashMap<String, BTreeSet<ProxyItemId>>) {
    let snap = st.index.latest();
    let live_users = st.local.live.users();
    for (user, mut ids) in pending {
        if !live_users.contains(&user) {
            continue;
        }
        if let Some(snap) = &snap {
            // Jellyfin also reports the season and series of each item.
            let parents: Vec<ProxyItemId> = ids
                .iter()
                .filter_map(|id| snap.item_index(id))
                .filter_map(|i| snap.items[i].season.or(snap.items[i].series))
                .map(|p| snap.items[p].id.clone())
                .collect();
            ids.extend(parents);
        }
        let list: Vec<Value> = ids
            .iter()
            .map(|id| view::user_dto(&st.userdata, &user, id, None, st.userdata.runtime(id)))
            .collect();
        let msg = envelope(
            "UserDataChanged",
            Some(json!({"UserId": user, "UserDataList": list})),
        );
        st.local.live.send_user(&user, &msg);
    }
}

/// What differs between two snapshots, by canonical id.
#[derive(Debug, Default)]
pub struct Diff {
    pub added: Vec<ProxyItemId>,
    pub removed: Vec<ProxyItemId>,
    pub updated: Vec<ProxyItemId>,
}

pub fn diff(old: &Snapshot, new: &Snapshot) -> Diff {
    let mut d = Diff::default();
    for (id, i) in new.ids() {
        match old.item_index(id) {
            None => d.added.push(id.clone()),
            Some(o) => {
                let (a, b) = (&old.items[o], &new.items[i]);
                let (pa, pb) = (old.primary(a), new.primary(b));
                let same = pa.kind == pb.kind
                    && pa.name == pb.name
                    && pa.sort_name == pb.sort_name
                    && pa.runtime == pb.runtime
                    && pa.premiere == pb.premiere
                    && pa.official == pb.official
                    && a.libraries == b.libraries
                    && a.copies.len() == b.copies.len();
                if !same {
                    d.updated.push(id.clone());
                }
            }
        }
    }
    d.removed = old
        .ids()
        .filter(|(id, _)| new.item_index(id).is_none())
        .map(|(id, _)| id.clone())
        .collect();
    d
}

/// Tell every user with a session what the index rebuild changed.
pub fn spawn_library(weak: Weak<AppState>) {
    let Some(st) = weak.upgrade() else { return };
    let mut rx = st.index.subscribe();
    drop(st);
    tokio::spawn(async move {
        loop {
            let (old, new) = match rx.recv().await {
                Ok(p) => p,
                Err(RecvError::Lagged(_)) => continue,
                Err(RecvError::Closed) => return,
            };
            let Some(old) = old else { continue };
            let Some(st) = weak.upgrade() else { return };
            let users = st.local.live.users();
            if users.is_empty() {
                continue;
            }
            let d = diff(&old, &new);
            if d.added.is_empty() && d.removed.is_empty() && d.updated.is_empty() {
                continue;
            }
            for user in users {
                if let Some(msg) = library_message(&st, &user, &old, &new, &d).await {
                    st.local.live.send_user(&user, &msg);
                }
            }
        }
    });
}

/// `(server, library id)` -> the user's views that contain it.
async fn view_map(
    st: &Shared,
    user: &str,
    new: &Snapshot,
) -> (HashMap<(ServerId, String), Vec<String>>, Vec<String>) {
    let c = Client {
        token: String::new(),
        user_id: user.to_string(),
        session: None,
    };
    let mut map: HashMap<(ServerId, String), Vec<String>> = HashMap::new();
    let mut all = vec![];
    for v in proxy::views(st, &c, false).await {
        let Some(id) = v.get("Id").and_then(Value::as_str) else {
            continue;
        };
        all.push(id.to_string());
        if let Some(crate::index::query::Scope::Libraries(libs)) = proxy::scope_of(st, new, id) {
            for l in libs {
                map.entry(l).or_default().push(id.to_string());
            }
        }
    }
    (map, all)
}

async fn library_message(
    st: &Shared,
    user: &str,
    old: &Snapshot,
    new: &Snapshot,
    d: &Diff,
) -> Option<String> {
    let visible = |ids: &[ProxyItemId]| -> Vec<String> {
        ids.iter()
            .filter(|id| !st.parental.blocks(user, id))
            .map(|id| id.as_str().to_string())
            .collect()
    };
    let added = visible(&d.added);
    let updated = visible(&d.updated);
    let removed: Vec<String> = d.removed.iter().map(|i| i.as_str().to_string()).collect();
    if added.is_empty() && updated.is_empty() && removed.is_empty() {
        return None;
    }
    let (map, all_views) = view_map(st, user, new).await;
    let folders = |snap: &Snapshot, ids: &[ProxyItemId]| -> Vec<String> {
        let set: BTreeSet<&String> = ids
            .iter()
            .filter_map(|id| snap.item(id))
            .flat_map(|it| it.libraries.iter())
            .filter_map(|l| map.get(l))
            .flatten()
            .collect();
        set.into_iter().cloned().collect()
    };
    let added_to = folders(new, &d.added);
    let removed_from = folders(old, &d.removed);
    let collection = if added.is_empty() && removed.is_empty() {
        vec![]
    } else {
        all_views
    };
    Some(envelope(
        "LibraryChanged",
        Some(json!({
            "FoldersAddedTo": added_to,
            "FoldersRemovedFrom": removed_from,
            "ItemsAdded": added,
            "ItemsRemoved": removed,
            "ItemsUpdated": updated,
            "CollectionFolders": collection,
            "IsEmpty": false,
        })),
    ))
}
